func newTrainingExportRecord() unsafe.Pointer {
	return unsafe.Pointer(new(aitraining.TrainingExportRecord))
}

func newNTrainingExportRecord(n int) unsafe.Pointer {
	return unsafe.Pointer(unsafe.SliceData(make([]aitraining.TrainingExportRecord, n)))
}

func ptrTrainingExportRecord(p unsafe.Pointer, c int32) any {
	r := (*aitraining.TrainingExportRecord)(p)
	switch c {
	case 0:
		return (*string)(unsafe.Pointer(&r.ID))
	case 1:
		return (*string)(unsafe.Pointer(&r.BusinessUnitID))
	case 2:
		return (*string)(unsafe.Pointer(&r.OrganizationID))
	case 3:
		return (*string)(unsafe.Pointer(&r.ExportID))
	case 4:
		return (*string)(unsafe.Pointer(&r.CorrectionID))
	case 5:
		return &r.ExampleID
	case 6:
		return (*string)(unsafe.Pointer(&r.Split))
	case 7:
		return &r.ConsentGrantedAt
	case 8:
		return &r.ExportedAt
	case 9:
		return &r.CreatedAt
	}
	return nil
}

func valueTrainingExportRecord(p unsafe.Pointer, c int32) any {
	r := (*aitraining.TrainingExportRecord)(p)
	switch c {
	case 0:
		return string(r.ID)
	case 1:
		return string(r.BusinessUnitID)
	case 2:
		return string(r.OrganizationID)
	case 3:
		return string(r.ExportID)
	case 4:
		return string(r.CorrectionID)
	case 5:
		return r.ExampleID
	case 6:
		return string(r.Split)
	case 7:
		return r.ConsentGrantedAt
	case 8:
		return r.ExportedAt
	case 9:
		return r.CreatedAt
	}
	return nil
}

